cat > src/server/repositories/member-absence-repository.ts <<'EOF'
/**
 * Out-of-office rows. Every read and write is filtered by `orgId`; a row is
 * removed outright when its member leaves, so there is no archive scope.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { SetAbsenceInput } from "@/schemas/member";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Replaces any absence the member already has in this workspace. */
export async function upsertAbsence(
  orgId: OrgId,
  input: Omit<SetAbsenceInput, "orgId">,
): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/** Drops `delegateUserId` from every absence naming this user as delegate. */
export async function clearDelegate(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}
