absence = '''/**
 * Records an out-of-office window. Anyone may set their own; setting someone
 * else's needs `member:update_role`. The delegate, when given, must be another
 * active member of the workspace.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  if (Date.parse(input.endsAt) <= Date.parse(input.startsAt)) {
    throw new Error("An absence must end after it starts");
  }

  const member = await requireActiveMember(input.orgId, input.userId);
  if (actor.userId !== input.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return memberAbsenceRepo.upsertAbsence(input.orgId, input);
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  if (actor.userId !== userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await memberAbsenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The absence still in force for `userId`: a scheduled one counts, an ended
 * one does not. Any active member of the workspace may read it.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));

  await requireActiveMember(orgId, userId);

  const absence = await memberAbsenceRepo.findAbsence(orgId, userId);
  if (absence === null) return null;
  return Date.parse(absence.endsAt) > Date.now() ? absence : null;
}

/**
 * The delegate who takes over `userId`'s work at instant `at`, or `null` when
 * the member is not away then or has no delegate. Stored state is not checked
 * for the delegate's own absence; callers decide whether that matters.
 */
export async function activeDelegateOf(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberAbsenceRepo.findAbsence(orgId, userId);
  if (absence === null || !isAwayAt(absence, at)) return null;
  return absence.delegateUserId;
}

/**
 * Where an assignment to `assigneeId` lands, decided at `at`. Assigning to
 * oneself is never redirected, and delegation is never chained: an assignee
 * whose delegate is away too keeps the issue.
 */
export async function redirectAssignee(
  orgId: OrgId,
  assigneeId: UserId | null,
  assignerId: UserId,
  at: Date,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === assignerId) return assigneeId;

  const delegate = await activeDelegateOf(orgId, assigneeId, at);
  if (delegate === null) return assigneeId;

  const delegateAbsence = await memberAbsenceRepo.findAbsence(orgId, delegate);
  if (delegateAbsence !== null && isAwayAt(delegateAbsence, at)) {
    return assigneeId;
  }
  return delegate;
}

function isAwayAt(absence: MemberAbsence, at: Date): boolean {
  const instant = at.getTime();
  return (
    Date.parse(absence.startsAt) <= instant &&
    instant < Date.parse(absence.endsAt)
  );
}

/** A live member whose status is `active`; anything else is not found. */
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

